import pandas as pd

try:
    df = pd.read_excel('/root/data.xlsx', header=None)
    # Search for the header row
    for i, row in df.iterrows():
        if row.astype(str).str.contains('Turn|Game|Die|1', regex=True).any():
             # Check if it looks like a header (multiple non-nan values)
             if row.count() > 3:
                print(f"Potential header at row {i}:")
                print(row)
                print("Next 5 rows:")
                print(df.iloc[i+1:i+6])
                break
except Exception as e:
    print(e)

